// Test-only copy of production SQLITE_PYTHON_EXECUTESCRIPT.
export const SQLITE_PYTHON_EXECUTESCRIPT = [
  "import re, sqlite3, sys, unicodedata",
  "db_path = sys.argv[1]",
  "sql = sys.stdin.read()",
  `timeout = int(sys.argv[2]) if len(sys.argv) > 2 else ${20}`,
  "ALLOWED_PRAGMAS = frozenset({",
  '    "busy_timeout", "wal_checkpoint", "user_version", "encoding",',
  '    "foreign_keys", "journal_mode", "synchronous", "temp_store",',
  "})",
  "FORBIDDEN_FUNCS = frozenset({",
  '    "load_extension", "writefile", "readfile", "edit", "fts3_tokenizer",',
  "})",
  "FORBIDDEN_STMT = re.compile(",
  '    r"\\b(attach|detach|vacuum)\\b", re.I',
  ")",
  "FORBIDDEN_CALL = re.compile(",
  '    r"\\b(load_extension|writefile|readfile|edit|fts3_tokenizer)\\s*\\(", re.I',
  ")",
  "ALLOWED_AUTHORIZER_ACTIONS = frozenset({",
  "    sqlite3.SQLITE_SELECT,",
  "    sqlite3.SQLITE_READ,",
  "    sqlite3.SQLITE_INSERT,",
  "    sqlite3.SQLITE_UPDATE,",
  "    sqlite3.SQLITE_DELETE,",
  "    sqlite3.SQLITE_TRANSACTION,",
  "    sqlite3.SQLITE_SAVEPOINT,",
  "    sqlite3.SQLITE_FUNCTION,",
  "    sqlite3.SQLITE_PRAGMA,",
  "})",
  "",
  "def _is_cf(ch):",
  "    return len(ch) == 1 and unicodedata.category(ch) == 'Cf'",
  "",
  "def _reject_outside_single_quoted(ch):",
  "    if len(ch) != 1:",
  "        return",
  "    if ord(ch) > 0x7f or _is_cf(ch):",
  "        raise sqlite3.OperationalError('non-ascii outside string literal')",
  "",
  "def _is_ws(ch):",
  "    return ch in ' \\t\\n\\f\\r'",
  "",
  "def _authorizer(action, p1, p2, dbname, trigger):",
  "    if action not in ALLOWED_AUTHORIZER_ACTIONS:",
  "        return sqlite3.SQLITE_DENY",
  "    if action == sqlite3.SQLITE_PRAGMA:",
  "        name = (p1 or '').split('(')[0].strip().lower()",
  "        if name not in ALLOWED_PRAGMAS:",
  "            return sqlite3.SQLITE_DENY",
  "    if action == sqlite3.SQLITE_FUNCTION:",
  "        fname = (p2 or '').lower()",
  "        if fname in FORBIDDEN_FUNCS:",
  "            return sqlite3.SQLITE_DENY",
  "    return sqlite3.SQLITE_OK",
  "",
  "def _split_statements(script):",
  "    out = []",
  "    buf = []",
  "    state = 'n'",
  "    i = 0",
  "    while i < len(script):",
  "        ch = script[i]",
  "        nxt = script[i + 1] if i + 1 < len(script) else ''",
  "        if state == 'n':",
  "            _reject_outside_single_quoted(ch)",
  "            if _is_ws(ch):",
  "                buf.append(ch)",
  "                i += 1",
  "                continue",
  "            if ch == '-' and nxt == '-':",
  "                i += 2",
  "                while i < len(script) and script[i] != '\\n':",
  "                    i += 1",
  "                continue",
  "            if ch == '/' and nxt == '*':",
  "                i += 2",
  "                while i < len(script):",
  "                    if script[i] == '*' and i + 1 < len(script) and script[i + 1] == '/':",
  "                        i += 2",
  "                        break",
  "                    i += 1",
  "                else:",
  "                    i = len(script)",
  "                continue",
  "            if ch == \"'\":",
  "                state = 's'",
  "                buf.append(ch)",
  "                i += 1",
  "                continue",
  "            if ch in 'Xx' and nxt == \"'\":",
  "                state = 'b'",
  "                buf.append(ch)",
  "                buf.append(nxt)",
  "                i += 2",
  "                continue",
  "            if ch == '\"':",
  "                state = 'd'",
  "                buf.append(ch)",
  "                i += 1",
  "                continue",
  "            if ch == '`':",
  "                state = 't'",
  "                buf.append(ch)",
  "                i += 1",
  "                continue",
  "            if ch == '[':",
  "                state = 'k'",
  "                buf.append(ch)",
  "                i += 1",
  "                continue",
  "            if ch == ';':",
  "                stmt = ''.join(buf).strip()",
  "                if stmt:",
  "                    out.append(stmt)",
  "                buf = []",
  "                i += 1",
  "                continue",
  "            buf.append(ch)",
  "            i += 1",
  "            continue",
  "        if state == 's':",
  "            buf.append(ch)",
  "            if ch == \"'\" and nxt == \"'\":",
  "                buf.append(nxt)",
  "                i += 2",
  "                continue",
  "            if ch == \"'\":",
  "                state = 'n'",
  "            i += 1",
  "            continue",
  "        if state == 'b':",
  "            buf.append(ch)",
  "            if ch == \"'\":",
  "                state = 'n'",
  "            i += 1",
  "            continue",
  "        if state == 'd':",
  "            _reject_outside_single_quoted(ch)",
  "            buf.append(ch)",
  "            if ch == '\"' and nxt == '\"':",
  "                buf.append(nxt)",
  "                i += 2",
  "                continue",
  "            if ch == '\"':",
  "                state = 'n'",
  "            i += 1",
  "            continue",
  "        if state == 't':",
  "            _reject_outside_single_quoted(ch)",
  "            buf.append(ch)",
  "            if ch == '`' and nxt == '`':",
  "                buf.append(nxt)",
  "                i += 2",
  "                continue",
  "            if ch == '`':",
  "                state = 'n'",
  "            i += 1",
  "            continue",
  "        if state == 'k':",
  "            _reject_outside_single_quoted(ch)",
  "            buf.append(ch)",
  "            if ch == ']':",
  "                state = 'n'",
  "            i += 1",
  "            continue",
  "    tail = ''.join(buf).strip()",
  "    if tail:",
  "        out.append(tail)",
  "    return out",
  "",
  "def _security_surface(stmt):",
  "    surface = []",
  "    state = 'n'",
  "    word = []",
  "    prev_end = 0",
  "    i = 0",
  "    while i < len(stmt):",
  "        ch = stmt[i]",
  "        nxt = stmt[i + 1] if i + 1 < len(stmt) else ''",
  "        if state == 'n':",
  "            _reject_outside_single_quoted(ch)",
  "            if _is_ws(ch):",
  "                if word:",
  "                    surface.append(''.join(word))",
  "                    word = []",
  "                i += 1",
  "                continue",
  "            if ch == '-' and nxt == '-':",
  "                if word:",
  "                    surface.append(''.join(word))",
  "                    word = []",
  "                i += 2",
  "                while i < len(stmt) and stmt[i] != '\\n':",
  "                    i += 1",
  "                prev_end = i",
  "                continue",
  "            if ch == '/' and nxt == '*':",
  "                if word:",
  "                    surface.append(''.join(word))",
  "                    word = []",
  "                i += 2",
  "                while i < len(stmt):",
  "                    if stmt[i] == '*' and i + 1 < len(stmt) and stmt[i + 1] == '/':",
  "                        i += 2",
  "                        break",
  "                    i += 1",
  "                else:",
  "                    i = len(stmt)",
  "                prev_end = i",
  "                continue",
  "            if ch == \"'\":",
  "                if word:",
  "                    surface.append(''.join(word))",
  "                    word = []",
  "                if prev_end < i and surface and re.search(r'[ \\t\\n\\f\\r]', stmt[prev_end:i]):",
  "                    surface.append(' ')",
  "                surface.append(' ')",
  "                state = 's'",
  "                i += 1",
  "                prev_end = i",
  "                continue",
  "            if ch in 'Xx' and nxt == \"'\":",
  "                if word:",
  "                    surface.append(''.join(word))",
  "                    word = []",
  "                surface.append(' ')",
  "                state = 'b'",
  "                i += 2",
  "                prev_end = i",
  "                continue",
  "            if ch in ('\"', '`', '['):",
  "                if word:",
  "                    surface.append(''.join(word))",
  "                    word = []",
  "                if prev_end < i and surface and re.search(r'[ \\t\\n\\f\\r]', stmt[prev_end:i]):",
  "                    surface.append(' ')",
  "                surface.append(' ')",
  "                state = 'd' if ch == '\"' else ('t' if ch == '`' else 'k')",
  "                i += 1",
  "                prev_end = i",
  "                continue",
  "            if ch.isascii() and (ch.isalnum() or ch == '_'):",
  "                if prev_end < i and word and re.search(r'[ \\t\\n\\f\\r]', stmt[prev_end:i]):",
  "                    surface.append(''.join(word))",
  "                    surface.append(' ')",
  "                    word = []",
  "                if not word:",
  "                    word = [ch]",
  "                else:",
  "                    word.append(ch)",
  "                i += 1",
  "                continue",
  "            if word:",
  "                surface.append(''.join(word))",
  "                word = []",
  "            surface.append(ch)",
  "            i += 1",
  "            prev_end = i",
  "            continue",
  "        if state == 's':",
  "            if ch == \"'\" and nxt == \"'\":",
  "                i += 2",
  "                continue",
  "            if ch == \"'\":",
  "                state = 'n'",
  "                prev_end = i + 1",
  "            i += 1",
  "            continue",
  "        if state == 'b':",
  "            if ch == \"'\":",
  "                state = 'n'",
  "                prev_end = i + 1",
  "            i += 1",
  "            continue",
  "        if state == 'd':",
  "            _reject_outside_single_quoted(ch)",
  "            if ch == '\"' and nxt == '\"':",
  "                i += 2",
  "                continue",
  "            if ch == '\"':",
  "                state = 'n'",
  "                prev_end = i + 1",
  "            i += 1",
  "            continue",
  "        if state == 't':",
  "            _reject_outside_single_quoted(ch)",
  "            if ch == '`' and nxt == '`':",
  "                i += 2",
  "                continue",
  "            if ch == '`':",
  "                state = 'n'",
  "                prev_end = i + 1",
  "            i += 1",
  "            continue",
  "        if state == 'k':",
  "            _reject_outside_single_quoted(ch)",
  "            if ch == ']':",
  "                state = 'n'",
  "                prev_end = i + 1",
  "            i += 1",
  "            continue",
  "    if word:",
  "        surface.append(''.join(word))",
  "    return re.sub(r'[ \\t\\n\\f\\r]+', ' ', ''.join(surface)).strip()",
  "",
  "def _refuse_unsafe_statement(stmt):",
  "    surface = _security_surface(stmt)",
  "    if FORBIDDEN_STMT.search(surface) or FORBIDDEN_CALL.search(surface):",
  "        raise sqlite3.OperationalError('refused unsafe SQL statement')",
  "",
  "conn = sqlite3.connect(db_path, timeout=timeout)",
  "conn.enable_load_extension(False)",
  "conn.set_authorizer(_authorizer)",
  "if hasattr(sqlite3, 'SQLITE_LIMIT_ATTACHED'):",
  "    conn.setlimit(sqlite3.SQLITE_LIMIT_ATTACHED, 0)",
  "try:",
  "    for stmt in _split_statements(sql):",
  "        _refuse_unsafe_statement(stmt)",
  "        conn.execute(stmt)",
  "    conn.commit()",
  "finally:",
  "    conn.close()",
].join("\n");
